import numpy as np
from ase.io import read
from ase.data import atomic_numbers
from ase.units import invcm

# ---------- user settings ----------
cell_file   = "d3.gs.vasp"
modes_file  = "m.npy"
freqs_file  = "f.npy"
scale       = 0.20
prefix      = "mode_"
# -----------------------------------

def write_xsf_with_vectors(fname, atoms, vectors, comment=""):
    """
    Write an XSF containing positions + vectors (6 numbers/line).
    Extra '#' lines are ignored by XCrySDen and useful for metadata.
    """
    with open(fname, "w") as f:
        f.write("# " + comment + "\n")
        f.write("CRYSTAL\nPRIMVEC\n")
        for a in atoms.cell:
            f.write(f" {a[0]:16.10f} {a[1]:16.10f} {a[2]:16.10f}\n")

        f.write("PRIMCOORD\n")
        f.write(f" {len(atoms)} 1\n")

        for pos, sym, vec in zip(atoms.positions,
                                 atoms.get_chemical_symbols(),
                                 vectors):
            Z = atomic_numbers[sym]
            f.write(f"{Z:3d}"
                    f"{pos[0]:16.10f}{pos[1]:16.10f}{pos[2]:16.10f}"
                    f"{vec[0]:16.10f}{vec[1]:16.10f}{vec[2]:16.10f}\n")

# ---------------- main batch export ----------------
atoms  = read(cell_file)
modes  = np.load(modes_file)
freqs  = np.load(freqs_file)

nat, nmode = len(atoms), modes.shape[1]
print(f"{nat} atoms, {nmode} Γ-point modes")

for m in range(nmode):
    disp  = modes[0, m].real * scale
    freq_eV = freqs[m]
    freq_cm = freq_eV / invcm

    tag   = f"{prefix}{m+1:03d}_{freq_cm:07.2f}cm-1.xsf"
    comment = (f"Mode {m+1}   Frequency = {freq_cm:.2f} cm^-1 "
               f"(={freq_eV:.5f} eV)   scale = {scale} Å")
    write_xsf_with_vectors(tag, atoms, disp, comment)
    print("  wrote", tag)
#==================================================================================
